  const [collapsed, setCollapsed] = useState<SplitBoxCollapsed>(false)

  return (
    <Column gap={32} width="fill">
      <Column gap={8}>
        <Text typo="label-medium">Uncontrolled horizontal split</Text>
        <SplitBox
          defaultSize="35%"
          minStart={128}
