          collapsible="both"
          collapseThreshold={32}
          expandThreshold={64}
          step={16}
          thickness={2}
          viewProps={{ width: 'fill', height: 160 }}
        >
          <SplitBoxPane>
            <Pane>Start pane</Pane>
          </SplitBoxPane>
          <SplitBoxPane>
            <Pane>End pane</Pane>
          </SplitBoxPane>
        </SplitBox>
      </Column>

      <Column gap={8}>
        <Text typo="label-medium">Vertical split with a disabled splitter</Text>
        <SplitBox
          direction="vertical"
          defaultSize={64}
          minStart={48}
          minEnd={48}
          disabled
          viewProps={{ width: 'fill', height: 160 }}
        >
          <SplitBoxPane>
            <Pane>Top pane</Pane>
          </SplitBoxPane>
          <SplitBoxPane>
            <Pane>Bottom pane</Pane>
